const API_URL = '__TIBIAWIKI_API_URL__';
const API_TOKEN = '__TIBIAWIKI_API_TOKEN__';

if (API_URL.includes('__TIBIAWIKI_') || API_TOKEN.includes('__TIBIAWIKI_')) {
  return 'A TibiaWiki HTTP Tool ainda nao foi configurada. Gere o workflow local com scripts/configure_n8n_http_workflow.py.';
}

let sql = '';
if (typeof query === 'string') {
  sql = query.trim();
} else if (typeof query === 'object' && query !== null) {
  sql = String(query.query || query.sql || query.input || '').trim();
}

if (!sql) {
  return 'Consulta SQL vazia. Envie um unico SELECT com LIMIT de no maximo 20 linhas.';
}

try {
  const result = await this.helpers.httpRequest({
    method: 'POST',
    url: API_URL,
    headers: {
      Authorization: `Bearer ${API_TOKEN}`,
      'Content-Type': 'application/json'
    },
    body: { query: sql },
    json: true,
    timeout: 15000
  });

  return JSON.stringify(result);
} catch (error) {
  return `Erro ao consultar a TibiaWiki: ${error.message}`;
}

let charName = '';
if (typeof query === 'string') {
  charName = query.trim();
} else if (typeof query === 'object' && query !== null) {
  charName = query.input || query.name || query.query || JSON.stringify(query);
} else {
  charName = String(query || '');
}
charName = charName.replace(/^[\"']|[\"']$/g, '').trim();

if (!charName) {
  return 'Nome de personagem inválido.';
}

try {
  let data;
  if (this && this.helpers && this.helpers.httpRequest) {
    data = await this.helpers.httpRequest({
      method: 'GET',
      url: `https://api.tibiadata.com/v4/character/${encodeURIComponent(charName)}`,
      json: true
    });
  } else if (typeof fetch !== 'undefined') {
    const res = await fetch(`https://api.tibiadata.com/v4/character/${encodeURIComponent(charName)}`);
    data = await res.json();
  } else if (typeof $helpers !== 'undefined' && $helpers.httpRequest) {
    data = await $helpers.httpRequest({
      method: 'GET',
      url: `https://api.tibiadata.com/v4/character/${encodeURIComponent(charName)}`,
      json: true
    });
  }

  if (!data || !data.character || !data.character.character || !data.character.character.name) {
    return `Personagem "${charName}" não foi encontrado no Tibia oficial.`;
  }

  const c = data.character.character;
  let guildInfo = 'Nenhuma';
  if (c.guild && c.guild.name) {
    guildInfo = `${c.guild.rank || 'Membro'} da ${c.guild.name}`;
  }

  let deathsInfo = 'Nenhuma morte recente registrada';
  if (Array.isArray(data.character.deaths) && data.character.deaths.length > 0) {
    deathsInfo = data.character.deaths.slice(0, 3).map(d => `${d.time}: Morto no level ${d.level} por ${d.reason || (d.killers && d.killers[0] ? d.killers[0].name : 'desconhecido')}`).join(' | ');
  }

  let status = 'offline';
  if (Array.isArray(data.character.other_characters)) {
    const me = data.character.other_characters.find(o => o.name.toLowerCase() === c.name.toLowerCase());
    if (me && me.status) {
      status = me.status;
    }
  }

  return JSON.stringify({
    nome: c.name,
    level: c.level,
    vocacao: c.vocation,
    mundo: c.world,
    status: status,
    residencia: c.residence,
    guilda: guildInfo,
    ultimo_login: c.last_login || 'Nunca',
    status_conta: c.account_status,
    mortes_recentes: deathsInfo
  });
} catch (err) {
  return `Erro ao consultar a API do TibiaData: ${err.message}`;
}

let worldName = '';
if (typeof query === 'string') {
  worldName = query.trim();
} else if (typeof query === 'object' && query !== null) {
  worldName = query.input || query.world || query.name || query.query || JSON.stringify(query);
} else {
  worldName = String(query || '');
}
worldName = worldName.replace(/^[\"']|[\"']$/g, '').trim();

if (!worldName) {
  return 'Nome de mundo/servidor inválido.';
}

try {
  let data;
  if (this && this.helpers && this.helpers.httpRequest) {
    data = await this.helpers.httpRequest({
      method: 'GET',
      url: `https://api.tibiadata.com/v4/world/${encodeURIComponent(worldName)}`,
      json: true
    });
  } else if (typeof fetch !== 'undefined') {
    const res = await fetch(`https://api.tibiadata.com/v4/world/${encodeURIComponent(worldName)}`);
    data = await res.json();
  } else if (typeof $helpers !== 'undefined' && $helpers.httpRequest) {
    data = await $helpers.httpRequest({
      method: 'GET',
      url: `https://api.tibiadata.com/v4/world/${encodeURIComponent(worldName)}`,
      json: true
    });
  }

  if (!data || !data.world || !data.world.name) {
    return `Mundo/servidor "${worldName}" não foi encontrado no Tibia oficial.`;
  }

  const w = data.world;
  return JSON.stringify({
    mundo: w.name,
    status: w.status,
    jogadores_online: w.players_online,
    tipo_pvp: w.pvp_type,
    localizacao: w.location,
    tipo_servidor: w.server_type,
    battleye: w.battleye_protected ? 'Protegido por BattlEye' : 'Sem BattlEye'
  });
} catch (err) {
  return `Erro ao consultar o mundo no TibiaData: ${err.message}`;
}

const payload = $input.first().json;
if (!payload || !Array.isArray(payload.documents)) {
  throw new Error('A API nao retornou a lista documents do Tibia Knowledge.');
}

const clean = (text = '') => String(text)
  .replace(/\u00ad/g, '')
  .replace(/[ \t]+\n/g, '\n')
  .replace(/\n{3,}/g, '\n\n')
  .trim();

function chunkText(text, size = 1200, overlap = 180) {
  const chunks = [];
  let start = 0;
  while (start < text.length) {
    const end = Math.min(start + size, text.length);
    chunks.push(text.slice(start, end));
    if (end === text.length) break;
    start = end - overlap;
  }
  return chunks;
}

const output = [];
for (const document of payload.documents) {
  const text = clean(document.text);
  if (!text) continue;
  const chunks = chunkText(text);
  chunks.forEach((chunk, index) => {
    output.push({
      json: {
        text: chunk,
        metadata: {
          ...(document.metadata || {}),
          document_id: document.id,
          chunk: index + 1,
          chunk_count: chunks.length
        }
      }
    });
  });
}

if (!output.length) {
  throw new Error('Nenhum documento valido foi preparado para embeddings.');
}
return output;

